function parse(req,max=12000){return new Promise((resolve,reject)=>{let bytes=0,chunks=[];req.on('data',c=>{bytes+=c.length;if(bytes>max){reject(Object.assign(Error('Request too large'),{status:413}));req.destroy();return;}chunks.push(c)});req.on('end',()=>{try{resolve(JSON.parse(Buffer.concat(chunks).toString()||'{}'))}catch{reject(Object.assign(Error('Invalid JSON'),{status:400}))}});req.on('error',reject)})}
function origin(req){if(!req.headers.origin)return true;try{return new URL(req.headers.origin).host===req.headers.host}catch{return false}}
function safeText(v,max){return typeof v==='string'?v.trim().slice(0,max):''}
function integer(v,min,max){return Number.isSafeInteger(Number(v))&&Number(v)>=min&&Number(v)<=max?Number(v):null}
function storage(){const {R2_ACCOUNT_ID,R2_ACCESS_KEY_ID,R2_SECRET_ACCESS_KEY,R2_BUCKET}=process.env;if(!R2_ACCOUNT_ID||!R2_ACCESS_KEY_ID||!R2_SECRET_ACCESS_KEY||!R2_BUCKET)return null;return require('./lib/review-storage').configuration({account:R2_ACCOUNT_ID,key:R2_ACCESS_KEY_ID,secret:R2_SECRET_ACCESS_KEY,bucket:R2_BUCKET},process.env)}
function hmac(key,msg){return crypto.createHmac('sha256',key).update(msg).digest()}
function presign(s,key,action,expires=900){
 if(s.reviewProxy)return require('./lib/review-storage').ticket(s,key,action,expires);
 const now=new Date(),stamp=now.toISOString().replace(/[:-]|\.\d{3}/g,''),date=stamp.slice(0,8),region='auto',service='s3',host=s.account+'.r2.cloudflarestorage.com';
 const uri='/'+[s.bucket,...key.split('/')].map(encodeURIComponent).join('/');
 const scope=date+'/'+region+'/'+service+'/aws4_request';
 const args=new URLSearchParams({'X-Amz-Algorithm':'AWS4-HMAC-SHA256','X-Amz-Credential':s.key+'/'+scope,'X-Amz-Date':stamp,'X-Amz-Expires':String(expires),'X-Amz-SignedHeaders':'host'});
 const query=[...args.entries()].map(([k,v])=>[encodeURIComponent(k),encodeURIComponent(v)]).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>k+'='+v).join('&');
 const method=action==='get'?'GET':action==='head'?'HEAD':'PUT';
 const canonical=[method,uri,query,'host:'+host+'\n','host','UNSIGNED-PAYLOAD'].join('\n');
 const stringToSign=['AWS4-HMAC-SHA256',stamp,scope,crypto.createHash('sha256').update(canonical).digest('hex')].join('\n');
 const signing=hmac(hmac(hmac(hmac('AWS4'+s.secret,date),region),service),'aws4_request');
 const sig=crypto.createHmac('sha256',signing).update(stringToSign).digest('hex');
 return 'https://'+host+uri+'?'+query+'&X-Amz-Signature='+sig;
}
