const demoWalletScript="<script>(function(){async function refreshWallet(){var p=document.getElementById('wallet-balance');if(!p)return;try{var r=await fetch('/api/demo/wallet');var x=await r.json();if(!r.ok)throw Error(x.error);var m=n=>'$'+(n/100).toFixed(2);p.textContent='Referral: '+m(x.membershipCents)+' | Downloads: '+m(x.downloadCents)+' | Royalties: '+m(x.royaltiesCents)+' | Total: '+m(x.totalCents)+' | Available: '+m(x.availableCents);document.getElementById('wallet-history').textContent=x.withdrawals.map(w=>'#'+w.id+' '+m(w.amount_cents)+' '+w.status).join(' | ')||'No withdrawal requests';}catch(e){p.textContent=e.message}}var d=document.getElementById('dashboard');if(!d)return;var section=document.createElement('section');section.innerHTML='<h3>DEMO Earnings and Withdrawals</h3><p id=\"wallet-balance\">Loading…</p><form id=\"wallet-form\"><input id=\"wallet-amount\" type=\"number\" min=\"0.01\" step=\"0.01\" required placeholder=\"Amount in USD\"><button>Request DEMO withdrawal</button></form><p id=\"wallet-history\"></p><small>Simulation only. No real money transferred.</small>';section.style.cssText='padding:16px;margin:16px 0;border:1px solid #aaa;border-radius:12px';var placeholder=document.getElementById('demo-wallet-placeholder');if(placeholder)placeholder.replaceWith(section);else d.appendChild(section);section.id='demo-wallet';document.getElementById('wallet-form').onsubmit=async function(e){e.preventDefault();var cents=Math.round(Number(document.getElementById('wallet-amount').value)*100);try{var r=await fetch('/api/demo/withdraw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cents})});var x=await r.json();if(!r.ok)throw Error(x.error);alert('Demo withdrawal submitted. No real money transferred.');await refreshWallet()}catch(e){alert(e.message)}};setInterval(refreshWallet,12000);refreshWallet()})();</script>";
const onboardingHtml=String.raw`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artist membership | LAE-MUSIC</title><style>*{box-sizing:border-box}body{margin:0;background:linear-gradient(160deg,#221038,#110d23 65%);color:#fff;font:16px system-ui}main{max-width:1000px;margin:auto;padding:24px}nav{display:flex;gap:20px;align-items:center;flex-wrap:wrap}a{color:#f5b8e2}h1{font-size:clamp(32px,6vw,58px);line-height:1.1;margin:48px 0 12px}h1 em{font-style:normal;color:#f49ec9}.sub{color:#c7bcd2}.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:26px 0}.plan{background:#201831;border:2px solid #51415d;border-radius:22px;padding:24px;cursor:pointer;display:block}.plan:has(input:checked){border-color:#f17ac1;background:#31203f}.plan strong{font-size:23px}.plan b{display:block;font-size:40px;margin:18px 0}.plan small{color:#c6b4ce}.plan input{accent-color:#f17ac1}section{margin:22px 0;padding:24px;border-radius:18px;background:#211a32}input:not([type=radio]),select{display:block;width:100%;max-width:430px;background:#332a46;color:white;border:1px solid #655371;border-radius:9px;padding:13px;margin:8px 0 18px;font:inherit}button{border:0;border-radius:10px;background:#f17ac1;color:#1c1230;font-weight:800;padding:14px 22px;cursor:pointer;font:inherit}button.primary{font-weight:800}#message{color:#ffdf8a;white-space:pre-wrap}small{color:#cbbbd6}html{overflow-y:auto;scroll-behavior:smooth}body{min-height:100vh;overflow-x:hidden;overflow-y:auto}main{width:100%;padding-bottom:clamp(100px,14vh,180px)}nav{position:relative;z-index:2}section,details{min-width:0}#dashboard{display:grid;gap:16px;align-content:start}#dashboard>h2,#dashboard>p{margin:0}#dashboard>details{background:#2b213f;border:1px solid #665377;border-radius:14px;overflow:hidden}#dashboard>details>summary{cursor:pointer;list-style-position:inside;font-size:1.08rem;font-weight:700;padding:18px 20px;line-height:1.5}#dashboard>details[open]>summary{border-bottom:1px solid #665377;background:#382949}#dashboard>details>form,#dashboard>details>p,#dashboard>details>small,#dashboard>details>section{margin:16px 20px}#dashboard>details>section{max-width:calc(100% - 40px)}#dashboard input{max-width:100%}#dashboard button{max-width:100%;white-space:normal}#dashboard a{overflow-wrap:anywhere}#dashboard #referralLink{width:100%}.plans{align-items:stretch}.plan{min-width:0}@media(max-width:650px){main{padding:16px 14px 120px}nav{gap:12px}h1{margin-top:30px}section{padding:18px 14px}.plans{grid-template-columns:1fr}#dashboard>details>summary{padding:16px}#dashboard>details>form,#dashboard>details>p,#dashboard>details>small,#dashboard>details>section{margin:14px}#dashboard>details>section{max-width:calc(100% - 28px)}}[hidden]{display:none!important}:root{color-scheme:dark;--ink:#f9f4ff;--muted:#c8bdd5;--glass:rgba(37,24,58,.78);--line:rgba(236,197,255,.17);--pink:#ff85cc;--gold:#ffd19b}body{background:radial-gradient(ellipse 90% 55% at 90% 0%,rgba(144,63,158,.34),transparent 75%),radial-gradient(ellipse 70% 65% at 0% 40%,rgba(47,76,152,.25),transparent 75%),#0d0b19;color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,sans-serif}main{max-width:1120px}nav{background:rgba(19,15,34,.7);border:1px solid var(--line);border-radius:18px;padding:14px 20px;backdrop-filter:blur(20px);justify-content:space-between}nav strong{letter-spacing:.11em;font-size:1.1rem}nav a{color:#e7d9f2;text-decoration:none;font-size:.9rem}nav a:hover{color:#fff}h1{font-weight:850;letter-spacing:-.055em;max-width:780px}h1 em{color:var(--gold)}.sub{max-width:720px;line-height:1.7;color:var(--muted)}section{background:var(--glass);border:1px solid var(--line);box-shadow:0 18px 60px rgba(0,0,0,.15);backdrop-filter:blur(18px)}.plan{background:linear-gradient(155deg,rgba(80,53,107,.8),rgba(25,23,48,.94));border:1px solid var(--line);transition:transform .2s,border-color .2s,box-shadow .2s}.plan:hover{transform:translateY(-3px);border-color:rgba(255,133,204,.55);box-shadow:0 20px 40px rgba(0,0,0,.2)}.plan:has(input:checked){border-color:var(--pink);box-shadow:0 0 0 1px rgba(255,133,204,.35),0 15px 45px rgba(197,65,149,.12)}.plan b{letter-spacing:-.06em}.plan small{line-height:1.7;display:block}.dashboard-intro{padding:14px 0 10px}.dashboard-intro h2{font-size:clamp(27px,4vw,43px);letter-spacing:-.045em;margin:8px 0}.dashboard-intro p{color:var(--muted);line-height:1.6}.eyebrow{color:var(--gold);font-size:.72rem;font-weight:800;letter-spacing:.2em}.dashboard-actions{display:flex;flex-wrap:wrap;gap:10px;padding:8px 0 4px}.dashboard-actions a{display:inline-flex;align-items:center;justify-content:center;padding:13px 18px;border-radius:12px;font-weight:750;text-decoration:none;transition:transform .2s}.dashboard-actions a:hover{transform:translateY(-2px)}.action-primary{background:linear-gradient(115deg,#ff95c9,#ffcdab);color:#25162a}.action-secondary{background:rgba(255,255,255,.07);border:1px solid var(--line);color:#fff}.access-note{color:var(--muted);font-size:.9rem}#dashboard>details{border-radius:16px;border:1px solid var(--line);background:rgba(255,255,255,.045)}#dashboard>details[open]>summary{background:rgba(255,255,255,.06)}#dashboard>details>summary{font-weight:720}button{background:linear-gradient(115deg,#ff92c9,#ffc3aa);color:#22162a;font-weight:750}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--gold);outline-offset:3px}@media(max-width:650px){nav{padding:12px;gap:10px}nav a{font-size:.8rem}.dashboard-actions{display:grid;grid-template-columns:1fr 1fr}.dashboard-actions a{padding:13px 10px;font-size:.86rem}#dashboard{padding:18px 12px}}.dashboard-pulse{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:20px 0 26px}.dashboard-pulse>div{background:linear-gradient(140deg,rgba(112,72,128,.32),rgba(27,22,47,.8));border:1px solid var(--line);border-radius:16px;padding:20px 15px}.dashboard-pulse span{font-size:.8rem;color:#cfc1da;display:block}.dashboard-pulse strong{display:block;font-size:clamp(23px,3vw,36px);margin-top:8px}@media(max-width:700px){.dashboard-pulse{grid-template-columns:repeat(2,minmax(0,1fr))}}.dashboard-metrics{padding:18px 20px;border-radius:16px;border:1px solid rgba(255,210,235,.24);background:linear-gradient(120deg,rgba(91,49,115,.5),rgba(31,25,53,.8));color:#ffe7f4;font-weight:650;line-height:1.8;margin:16px 0}.dashboard-metrics:empty{display:none}</style></head><body><main><nav><strong>LAE-MUSIC</strong><a href="/">Home</a><a href="/music">Listen to music</a><a href="/start#signin">Sign In</a></nav><h1>Your music deserves <em>a bigger stage.</em></h1><p class="sub">Build your sound, grow your audience and manage your creative business from one account. Artist packages are currently in testing; no real payment is collected here.</p><p id="message" role="status"></p><section id="choose" hidden><h2>Choose your membership</h2><div class="plans"><label class="plan"><input type="radio" name="planChoice" value="starter" checked> <strong>Starter</strong><b>US$6</b><p>Per year</p><small>2 studio generations (up to 4 tracks), plus up to 3 quality-approved external uploads · 50% royalty · extra studio generation US$3</small></label><label class="plan"><input type="radio" name="planChoice" value="growth"> <strong>Growth</strong><b>US$10</b><p>Per year</p><small>3 studio generations (up to 6 tracks) · 50% royalty · extra studio generation US$2.50</small></label><label class="plan"><input type="radio" name="planChoice" value="professional"> <strong>Professional</strong><b>US$20</b><p>Per year</p><small>6 studio generations (up to 12 tracks) · 50% Premium Listener streaming royalty · extra studio generation US$2</small></label></div><label>View approximate price in <select id="currency"><option value="USD">USD</option><option value="NGN">NGN</option><option value="GHS">GHS</option><option value="KES">KES</option><option value="LRD">LRD</option><option value="ZAR">ZAR</option><option value="UGX">UGX</option><option value="TZS">TZS</option><option value="RWF">RWF</option><option value="BIF">BIF</option><option value="CDF">CDF</option><option value="XOF">XOF</option><option value="XAF">XAF</option><option value="GMD">GMD</option><option value="SLL">SLL</option><option value="GNF">GNF</option><option value="CVE">CVE</option><option value="MZN">MZN</option><option value="AOA">AOA</option><option value="ZMW">ZMW</option><option value="MWK">MWK</option><option value="BWP">BWP</option><option value="NAD">NAD</option><option value="LSL">LSL</option><option value="SZL">SZL</option><option value="MUR">MUR</option><option value="SCR">SCR</option><option value="MGA">MGA</option><option value="ETB">ETB</option><option value="DJF">DJF</option><option value="SOS">SOS</option><option value="SDG">SDG</option><option value="EGP">EGP</option><option value="MAD">MAD</option><option value="DZD">DZD</option><option value="TND">TND</option><option value="LYD">LYD</option><option value="MRU">MRU</option><option value="STN">STN</option><option value="KMF">KMF</option><option value="GBP">GBP</option><option value="EUR">EUR</option><option value="CHF">CHF</option><option value="SEK">SEK</option><option value="NOK">NOK</option><option value="DKK">DKK</option><option value="PLN">PLN</option><option value="CZK">CZK</option><option value="HUF">HUF</option><option value="RON">RON</option><option value="BGN">BGN</option><option value="TRY">TRY</option><option value="UAH">UAH</option><option value="ISK">ISK</option><option value="ALL">ALL</option><option value="RSD">RSD</option><option value="MKD">MKD</option><option value="BAM">BAM</option><option value="MDL">MDL</option><option value="GEL">GEL</option><option value="AMD">AMD</option><option value="AZN">AZN</option><option value="CAD">CAD</option><option value="AUD">AUD</option><option value="NZD">NZD</option><option value="BRL">BRL</option><option value="MXN">MXN</option><option value="ARS">ARS</option><option value="CLP">CLP</option><option value="COP">COP</option><option value="PEN">PEN</option><option value="UYU">UYU</option><option value="PYG">PYG</option><option value="BOB">BOB</option><option value="CRC">CRC</option><option value="DOP">DOP</option><option value="JMD">JMD</option><option value="TTD">TTD</option><option value="XCD">XCD</option><option value="BBD">BBD</option><option value="BSD">BSD</option><option value="BZD">BZD</option><option value="GTQ">GTQ</option><option value="HNL">HNL</option><option value="NIO">NIO</option><option value="PAB">PAB</option><option value="INR">INR</option><option value="PKR">PKR</option><option value="BDT">BDT</option><option value="LKR">LKR</option><option value="NPR">NPR</option><option value="CNY">CNY</option><option value="JPY">JPY</option><option value="KRW">KRW</option><option value="SGD">SGD</option><option value="MYR">MYR</option><option value="IDR">IDR</option><option value="THB">THB</option><option value="PHP">PHP</option><option value="VND">VND</option><option value="HKD">HKD</option><option value="TWD">TWD</option><option value="AED">AED</option><option value="SAR">SAR</option><option value="QAR">QAR</option><option value="KWD">KWD</option><option value="BHD">BHD</option><option value="OMR">OMR</option><option value="ILS">ILS</option><option value="JOD">JOD</option><option value="IQD">IQD</option></select></label><p id="price"></p><p><small>Conversions are estimates; actual payments are not enabled.</small></p><button class="primary" id="continue">Continue with selected plan</button></section><section id="register" hidden><h2>Create your artist account</h2><p id="selected"></p><form id="registerForm"><label>Artist name<input name="name" required minlength="2"></label><label>Country<input name="country" maxlength="100" minlength="2" autocomplete="country-name" required placeholder="e.g. Nigeria"></label><label>Email<input type="email" name="email" required></label><label>Password (at least 10 characters)<input id="registerPassword" type="password" name="password" minlength="10" autocomplete="new-password" required></label><button type="button" id="toggleRegisterPassword">Show password</button><label>Confirm password<input type="password" name="confirmPassword" minlength="10" autocomplete="new-password" required></label><button class="primary" type="submit">Create account and continue to membership</button><p id="registerHelp" style="color:#ffdf8a;font-size:14px" role="status" aria-live="polite"></p></form></section><section id="signin" hidden><h2>Sign in to your artist account</h2><form id="loginForm"><label>Email<input type="email" name="email" required></label><label>Password<input id="loginPassword" type="password" name="password" autocomplete="current-password" required></label><button type="button" id="togglePassword" aria-pressed="false">Show password</button> <button class="primary">Sign In</button><p><a href="/start#recovery" id="forgotLink">Forgot password?</a></p></form></section><section id="payment" hidden><h2>Demo membership activation</h2><p id="identity"></p><p id="membership"></p><button class="primary" id="demoPay">Activate with DEMO payment — no money charged</button><p><small>Demo only. This does not process a real payment.</small></p><button id="change">Change membership plan</button> <button id="logout">Sign out</button></section><section id="dashboard" hidden><div class="dashboard-intro"><span class="eyebrow">YOUR LAE-MUSIC SPACE</span><h2>One account. Your music business.</h2><p>Manage your profile, music, referrals and membership from one place.</p></div><p id="welcome"></p><div id="dashboardMetrics" class="dashboard-metrics" aria-live="polite">Loading your account overview…</div><div class="dashboard-actions"><a class="action-primary" id="artistAccess" href="/artist">Open artist studio</a><a class="action-secondary" href="/music">Explore music</a><a class="action-secondary" href="/affiliate-links">My referral links</a><a class="action-secondary" href="/start#payment">Artist packages</a></div><p id="accessNote" class="access-note" role="status"></p><details><summary>Artist profile and music statistics (tap to expand)</summary><form id="profileForm"><label>Public artist name<input id="profileName" name="displayName" required minlength="2" maxlength="100"></label><button type="submit">Save artist name</button></form><p id="artistStats">Loading music statistics…</p><small>Real payouts are not yet enabled.</small><section style='border:1px solid #66758d;padding:16px;border-radius:12px'><h3>Artist Earnings</h3><p>View your referral commissions, music royalties, available balance, and withdrawal history in one place.</p><p><a href='/earnings' style='display:inline-block;background:#dceaff;color:#13243b;padding:12px 16px;border-radius:9px;font-weight:700;text-decoration:none'>Open Earnings Dashboard</a></p><small>Demo balances only. Real payouts are not enabled.</small></section></details><details><summary>Affiliate programme and referral earnings (tap to expand)</summary><p>Invite artists with your personal referral link. Free affiliate membership. Commission applies only to verified purchases through qualifying product referral links. Team rewards are assessed quarterly; payouts are not yet active. <a href='/affiliate-links'>View product referral links</a>.</p><p><input id="referralLink" readonly aria-label="Your referral link"><button id="copyReferral" type="button">Copy referral link</button></p><p id="referralSummary">Loading referrals…</p><p id="affiliateEarnings">Verified affiliate commissions: loading…</p><p id="subscriptionStatus">Annual upload allowance: loading…</p><p><small>Demo membership activations do not earn real commissions. Paid downloads and withdrawals are not yet enabled.</small></p></details><details><summary>Account security — change password</summary><form id="passwordForm"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>New password (10+ characters)<input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label><button type="submit">Update password</button></form></details><button id="logout2">Sign out</button></section></main><script>const $=id=>document.getElementById(id),amount={starter:6,growth:10,professional:20};let rates={USD:1},current=null;async function api(url,method,data){const r=await fetch(url,{method:method||'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}function say(t){$('message').textContent=t}function chosen(){return document.querySelector('input[name=planChoice]:checked').value}function showPrice(){const usd=amount[chosen()],cur=$('currency').value,rate=rates[cur];$('price').textContent=rate?'Estimated: '+new Intl.NumberFormat('en',{style:'currency',currency:cur}).format(usd*rate):'US$'+usd+' (conversion unavailable)'}function view(id){for(const n of ['choose','register','signin','payment','dashboard'])$(n).hidden=n!==id}async function refresh(){try{current=(await api('/api/me')).user;if(location.hash==='#signin'){view('signin');return}if(current){if(location.hash==='#payment'){await payment();return}view('dashboard');api('/api/dashboard/summary').then(d=>{$('dashboardMetrics').textContent='Published tracks: '+d.music.published_songs+' | Direct sales: '+d.affiliate.direct_sales+' | Pending commissions: USD '+(Number(d.affiliate.pending_commissions_cents)/100).toFixed(2)+' | Team sales this quarter: '+d.affiliate.team_sales_this_quarter}).catch(e=>{$('dashboardMetrics').textContent='Account overview unavailable: '+e.message});api('/api/referrals').then(x=>{$('referralLink').value=x.referralLink;$('referralSummary').textContent='Artists referred: '+x.referredCount}).catch(e=>{$('referralSummary').textContent=e.message});api('/api/affiliate/earnings').then(x=>{$('affiliateEarnings').textContent='Subscription commissions: '+x.totals.reduce((n,c)=>n+Number(c.transactions),0)+' transactions; $'+(x.totals.reduce((n,c)=>n+Number(c.amount_cents),0)/100).toFixed(2)+' recorded (pending)'}).catch(e=>{$('affiliateEarnings').textContent=e.message});api('/api/artist/subscription').then(x=>{$('artistAccess').hidden=!x.artist_features_active;$('accessNote').textContent=x.artist_features_active?'Your artist tools are enabled under your current package.':'Affiliate dashboard active. Choose an artist package to unlock music publishing and artist tools.';$('subscriptionStatus').textContent='Annual uploads: '+x.uploads_used+'/'+x.upload_limit+(x.subscription?' - Renewal '+new Date(x.subscription.expires_at).toLocaleDateString():' - Demo account')}).catch(e=>{$('subscriptionStatus').textContent=e.message});$('welcome').textContent='Welcome, '+current.display_name+' - '+current.plan;$('profileName').value=current.display_name;api('/api/account/overview').then(x=>{$('artistStats').textContent='Songs: '+x.stats.tracks+' | Published: '+x.stats.published+' | Plays: '+x.stats.plays}).catch(e=>{$('artistStats').textContent='Music statistics unavailable: '+e.message});return}view('choose');showPrice();say('Create a free account to access your dashboard. Artist tools become available with an active package.')}catch{current=null;if(location.hash==='#signin')view('signin');else view('choose')}}$('continue').onclick=async()=>{try{if(current){await api('/api/artist/select-plan','POST',{plan:chosen()});await payment()}else{$('selected').textContent='Selected plan: '+chosen()+' — US$'+amount[chosen()]+'/year';view('register')}}catch(e){say(e.message)}};async function payment(){current=(await api('/api/me')).user;const ref=sessionStorage.getItem('lae_ref'),product=sessionStorage.getItem('lae_product');if(ref&&product===current.plan){try{const intent=await api('/api/affiliate/prepare-purchase','POST',{plan:current.plan,ref});sessionStorage.setItem('lae_purchase_token',intent.referral_token)}catch(err){say('Referral attribution could not be prepared: '+err.message)}}$('identity').textContent='Artist: '+current.display_name+' ('+current.email+')';$('membership').textContent='Selected: '+current.plan+' — US$'+amount[current.plan]+'/year';view('payment')} $('registerForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]');if(button.disabled)return;const fields=Object.fromEntries(new FormData(form));if(fields.password!==fields.confirmPassword){say('The two passwords do not match. Please correct them.');form.elements.confirmPassword.focus();return}button.disabled=true;button.textContent='Creating account…';$('registerHelp').textContent='Connecting to LAE-MUSIC…';say('Creating your artist account. Please wait…');try{fields.plan=chosen();fields.ref=new URLSearchParams(location.search).get('ref')||sessionStorage.getItem('lae_ref')||'';const created=await api('/api/register','POST',fields);current=created.user;$('identity').textContent='Artist: '+current.display_name+' ('+current.email+')';$('membership').textContent='Selected: '+current.plan+' — US$'+amount[current.plan]+'/year';view('dashboard');await refresh();say('Free affiliate account created. Artist publishing requires an active artist plan.')}catch(err){say('Registration could not be completed: '+err.message);$('registerHelp').textContent='Error: '+err.message}finally{button.disabled=false;button.textContent='Create account and continue to membership'}};const regForm=$('registerForm');regForm.addEventListener('invalid',e=>{const field=e.target;const label=field.closest('label');const name=label?label.textContent.trim().split('(')[0].trim():'This field';const msg=name+': '+field.validationMessage;$('registerHelp').textContent=msg;say('Please complete the highlighted registration field. '+msg) },true);regForm.addEventListener('input',()=>{$('registerHelp').textContent=''});$('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/login','POST',Object.fromEntries(new FormData(e.target)));location.hash='';say('Signed in');await refresh()}catch(err){say(err.message)}};$('demoPay').onclick=async()=>{if(!confirm('Confirm DEMO activation? No money will be charged.'))return;try{await api('/api/demo/activate','POST',{});await api('/api/logout','POST',{});current=null;location.hash='#signin';view('signin');say('Demo membership activated. Please sign in with your email and password to open your dashboard.')}catch(e){say(e.message)}};$('change').onclick=()=>{location.hash='';view('choose')};async function logout(){try{await api('/api/logout','POST',{});current=null;location.hash='';say('Signed out');await refresh()}catch(e){say(e.message)}}$('profileForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/account/profile','POST',Object.fromEntries(new FormData(e.target)));say('Artist name saved successfully.');await refresh()}catch(err){say(err.message)}};$('passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/account/password','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();say('Password changed successfully. Other sessions signed out.')}catch(err){say(err.message)}};$('copyReferral').onclick=async()=>{const v=$('referralLink').value;if(!v)return;try{await navigator.clipboard.writeText(v);say('Referral link copied')}catch{ $('referralLink').select();say('Select and copy your referral link')}};const incomingRef=new URLSearchParams(location.search).get('ref');if(incomingRef&&/^[1-9]\d{0,15}$/.test(incomingRef))sessionStorage.setItem('lae_ref',incomingRef);const linkedProduct=new URLSearchParams(location.search).get('product');if(['starter','growth','professional'].includes(linkedProduct)){sessionStorage.setItem('lae_product',linkedProduct);const choice=document.querySelector('input[name=planChoice][value="'+linkedProduct+'"]');if(choice)choice.checked=true;}$('logout').onclick=logout;$('logout2').onclick=logout;document.querySelectorAll('input[name=planChoice]').forEach(x=>x.onchange=showPrice);$('currency').onchange=showPrice;api('/api/exchange-rates').then(x=>{rates={USD:1,...x.rates};showPrice()}).catch(showPrice);$('toggleRegisterPassword').onclick=()=>{const p=$('registerPassword');p.type=p.type==='password'?'text':'password';$('toggleRegisterPassword').textContent=p.type==='password'?'Show password':'Hide password'};$('togglePassword').onclick=()=>{const p=$('loginPassword');const show=p.type==='password';p.type=show?'text':'password';$('togglePassword').textContent=show?'Hide password':'Show password';$('togglePassword').setAttribute('aria-pressed',String(show))};$('forgotLink').onclick=e=>{e.preventDefault();say('Password reset by email is not configured yet. Please contact LAE-MUSIC support for account recovery.');view('signin')};window.addEventListener('hashchange',refresh);refresh();</script></body></html>`;

const earningsHtml="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Artist Earnings | LAE-MUSIC</title><style>\n*{box-sizing:border-box}body{margin:0;background:#101522;color:#f2f5fc;font:16px/1.5 system-ui,sans-serif}main{max-width:1060px;margin:auto;padding:22px 16px 65px}header{display:flex;gap:14px;justify-content:space-between;flex-wrap:wrap;align-items:center;margin-bottom:32px}a{color:#bbd7ff}h1{font-size:clamp(30px,5vw,42px);margin:0}h2{font-size:21px;margin:0 0 12px}p{color:#cad2df}.tag{display:inline-block;padding:5px 12px;border-radius:20px;background:#304057;font-size:13px;font-weight:700}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:13px;margin:22px 0}.card,.panel{background:#1c2638;border:1px solid #40506a;border-radius:14px;padding:19px}.card small{color:#d0d9e7}.amount{font-size:29px;font-weight:750;margin-top:8px}.panels{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:15px}.panel{margin-top:6px}label{display:block;margin:12px 0 7px}input{width:100%;padding:13px;background:#101827;border:1px solid #8290a8;border-radius:9px;color:#fff;font:inherit}button{margin-top:12px;background:#b7ddff;color:#132336;border:0;border-radius:9px;padding:13px 18px;font:inherit;font-weight:700}button:disabled{opacity:.6}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px 5px;border-bottom:1px solid #40506a}th{font-size:13px;color:#d0d9e7}#status,#feedback{min-height:24px}.note{font-size:14px}.error{color:#ffbaba}.success{color:#a8f1c8}footer{margin-top:25px;color:#cbd2df;font-size:13px}\n</style></head><body><main><header><strong>LAE-MUSIC · Artist Finance</strong><nav><a href=\"/start\">Membership dashboard</a> · <a href=\"/artist\">Music studio</a></nav></header><h1>Your earnings</h1><p>All your referral earnings and withdrawal activity in one place.</p><span class=\"tag\">DEMO MODE · NO REAL MONEY</span><p id=\"status\" role=\"status\">Loading earnings…</p>\n<div class=\"cards\"><section class=\"card\"><small>Membership referrals</small><div class=\"amount\" id=\"membership\">$—</div></section><section class=\"card\"><small>Download commissions</small><div class=\"amount\" id=\"downloads\">$—</div></section><section class=\"card\"><small>Music royalties</small><div class=\"amount\" id=\"royalties\">$—</div></section><section class=\"card\"><small>Total demo earnings</small><div class=\"amount\" id=\"total\">$—</div></section><section class=\"card\"><small>Available balance</small><div class=\"amount\" id=\"available\">$—</div></section></div>\n<div class=\"panels\"><section class=\"panel\"><h2>Request demo withdrawal</h2><p class=\"note\">Requests are simulated. No bank transfer will take place.</p><form id=\"withdraw\"><label for=\"withdrawAmount\">Amount (USD)</label><input id=\"withdrawAmount\" type=\"number\" min=\"0.01\" step=\"0.01\" placeholder=\"1.00\" required><button id=\"submit\" type=\"submit\">Submit demo request</button></form><p id=\"feedback\" role=\"status\"></p></section><section class=\"panel\"><h2>Withdrawal history</h2><div style=\"overflow-x:auto\"><table><thead><tr><th>Request</th><th>Amount</th><th>Status</th></tr></thead><tbody id=\"history\"><tr><td colspan=\"3\">Loading…</td></tr></tbody></table></div></section></div><footer>Download referral earnings and music royalties will remain at zero until those payment features are implemented. All figures on this page are demo values.</footer></main>\n<script>\nconst byId=id=>document.getElementById(id);\nconst dollars=cents=>'$'+(Number(cents||0)/100).toFixed(2);\nasync function loadEarnings(){\n try{\n const response=await fetch('/api/demo/wallet',{credentials:'same-origin',cache:'no-store'});\n const data=await response.json();\n if(!response.ok)throw Error(data.error||'Wallet unavailable');\n for(const pair of [['membership',data.membershipCents],['downloads',data.downloadCents],['royalties',data.royaltiesCents],['total',data.totalCents],['available',data.availableCents]])byId(pair[0]).textContent=dollars(pair[1]);\n const history=byId('history');history.replaceChildren();\n if(!data.withdrawals.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=3;td.textContent='No withdrawal requests yet';tr.appendChild(td);history.appendChild(tr)}\n for(const w of data.withdrawals){const tr=document.createElement('tr');for(const value of ['#'+w.id,dollars(w.amount_cents),w.status]){const td=document.createElement('td');td.textContent=value;tr.appendChild(td)}history.appendChild(tr)}\n byId('status').textContent='Your demo earnings are up to date.';byId('status').className='success';\n }catch(error){byId('status').textContent='Could not load earnings: '+error.message;byId('status').className='error'}\n}\nbyId('withdraw').addEventListener('submit',async event=>{\n event.preventDefault();const cents=Math.round(Number(byId('withdrawAmount').value)*100);\n if(!Number.isSafeInteger(cents)||cents<1){byId('feedback').textContent='Enter a valid amount.';return}\n const button=byId('submit');button.disabled=true;byId('feedback').textContent='Submitting demo request…';\n try{\n const response=await fetch('/api/demo/withdraw',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({cents})});\n const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');\n byId('feedback').textContent='Demo request recorded. No real money transferred.';byId('feedback').className='success';byId('withdraw').reset();await loadEarnings();\n }catch(error){byId('feedback').textContent='Request failed: '+error.message;byId('feedback').className='error'}\n finally{button.disabled=false}\n});\nloadEarnings();\n</script></body></html>";
const adminWithdrawalsHtml="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>LAE-MUSIC · Admin Withdrawals</title><style>*{box-sizing:border-box}body{margin:0;background:#101726;color:#f0f4ff;font:16px/1.5 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:25px 16px}a{color:#b6d7ff}.panel{background:#1c293c;border:1px solid #43556f;border-radius:14px;padding:20px;margin:18px 0}h1{margin:0;font-size:32px}input{display:block;width:100%;padding:12px;margin:8px 0 12px;border:1px solid #8291a9;border-radius:8px;background:#101726;color:white;font:inherit}button{padding:10px 14px;margin:4px;border:0;border-radius:8px;background:#bbdfff;color:#102034;font:inherit;font-weight:650;cursor:pointer}button:disabled{opacity:.5}table{border-collapse:collapse;width:100%;min-width:550px}td,th{border-bottom:1px solid #43556f;padding:12px 6px;text-align:left}th{font-size:13px;color:#cdd9e9}.hint{color:#cbd5e6}#message{min-height:24px}</style></head><body><main><header><a href=\"/start\">← LAE-MUSIC</a></header><h1>Admin · Demo Withdrawals</h1><p class=\"hint\">Review simulated withdrawal requests. Approving does not send money.</p><section class=\"panel\" id=\"loginPanel\"><h2>Administrator sign in</h2><form id=\"login\"><label>Admin password<input type=\"password\" id=\"password\" autocomplete=\"current-password\" required></label><button type=\"submit\">Sign in</button></form></section><section class=\"panel\" id=\"reviewPanel\" hidden><h2>Withdrawal requests</h2><button id=\"reload\">Refresh requests</button><button id=\"logout\">Sign out</button><p id=\"summary\"></p><div style=\"overflow-x:auto\"><table><thead><tr><th>Request</th><th>Artist</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody id=\"requests\"></tbody></table></div></section><p id=\"message\" role=\"status\"></p></main><script>\nconst el=id=>document.getElementById(id);const usd=n=>'$'+(Number(n)/100).toFixed(2);\nasync function request(path,method,body){const r=await fetch(path,{method:method||'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,cache:'no-store'});const x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');return x}\nasync function load(){try{const data=await request('/api/demo/admin/withdrawals');el('loginPanel').hidden=true;el('reviewPanel').hidden=false;const tbody=el('requests');tbody.replaceChildren();el('summary').textContent=data.withdrawals.length+' recent requests';for(const w of data.withdrawals){const tr=document.createElement('tr');for(const value of ['#'+w.id,w.display_name,usd(w.amount_cents),w.status]){const td=document.createElement('td');td.textContent=value;tr.appendChild(td)}const td=document.createElement('td');if(w.status==='pending'){for(const status of ['approved','rejected']){const b=document.createElement('button');b.textContent=status==='approved'?'Approve':'Reject';b.onclick=async()=>{if(!confirm('Mark request #'+w.id+' as '+status+'? This is DEMO only.'))return;b.disabled=true;try{await request('/api/demo/admin/review','POST',{id:w.id,status});el('message').textContent='Request updated.';await load()}catch(e){el('message').textContent=e.message;b.disabled=false}};td.appendChild(b)}}else td.textContent='Reviewed';tr.appendChild(td);tbody.appendChild(tr)}if(!data.withdrawals.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='No demo withdrawal requests yet.';tr.appendChild(td);tbody.appendChild(tr)}}catch(e){el('loginPanel').hidden=false;el('reviewPanel').hidden=true;el('message').textContent=e.message}}\nel('login').onsubmit=async e=>{e.preventDefault();try{await request('/api/admin/login','POST',{password:el('password').value});el('password').value='';el('message').textContent='Signed in.';await load()}catch(err){el('message').textContent=err.message}};\nel('reload').onclick=load;el('logout').onclick=async()=>{try{await request('/api/admin/logout','POST',{});el('message').textContent='Signed out.';await load()}catch(e){el('message').textContent=e.message}};load();\n</script></body></html>";
const adminDashboardHtml="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>LAE-MUSIC Administration</title><style>*{box-sizing:border-box}body{margin:0;background:#120e22;color:#f9f4ff;font:15px/1.55 system-ui}header{padding:20px 30px;border-bottom:1px solid #433454;display:flex;justify-content:space-between}main{max-width:1200px;margin:auto;padding:28px 20px}h1{font-size:30px}h2{font-size:20px}button,input{font:inherit;padding:12px;border-radius:9px}input{background:#100d1d;color:white;border:1px solid #67577c;width:min(100%,360px)}button{border:0;background:#ed9bd4;color:#201026;cursor:pointer;font-weight:650}button:disabled{opacity:.5}nav{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}nav button{background:#342747;color:#fff}nav button[aria-selected=true]{background:#ed9bd4;color:#201026}.panel{background:#21192f;border:1px solid #443452;padding:22px;border-radius:15px;margin:16px 0}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.metrics div{background:#312540;padding:16px;border-radius:12px}.metrics strong{display:block;font-size:25px}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:720px}td,th{padding:10px;text-align:left;border-bottom:1px solid #453750}small,.muted{color:#c7b8d5}a{color:#f4b8e2}#status{min-height:25px}</style></head><body><header><strong>LAE-MUSIC · Administration</strong><span id=\"identity\">Secure management</span></header><main><section id=\"login\" class=\"panel\" hidden><h1>Administrator sign-in</h1><p>Enter the private administrator key to access management tools.</p><form id=\"loginForm\"><input id=\"password\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Administrator key\" required><button type=\"submit\">Sign in</button></form></section><section id=\"workspace\" hidden><h1>Admin Dashboard</h1><p class=\"muted\">Manage your platform from one protected workspace.</p><button id=\"logout\">Sign out</button><nav aria-label=\"Admin sections\"><button data-tab=\"overview\" aria-selected=\"true\">Overview</button><button data-tab=\"affiliates\">Affiliates & commissions</button><button data-tab=\"withdrawals\">Withdrawals (demo)</button><button data-tab=\"artists\">Artists & downlines</button><button data-tab=\"video\">Homepage video</button><button data-tab=\"studio\">Homepage Studio</button></nav><section id=\"overview\" class=\"panel\"><h2>Platform overview</h2><div class=\"metrics\" id=\"metrics\"></div></section><section id=\"affiliates\" class=\"panel\" hidden><h2>Affiliate commissions</h2><p class=\"muted\">Verified paid subscription records; direct 25%, indirect 10%. No automatic bank payout is connected.</p><div class=\"scroll\"><table><thead><tr><th>Affiliate</th><th>Referred artist</th><th>Plan</th><th>Tier</th><th>Commission</th><th>Status</th><th>Date</th></tr></thead><tbody id=\"commissions\"></tbody></table></div></section><section id=\"withdrawals\" class=\"panel\" hidden><h2>Demo withdrawal requests</h2><p class=\"muted\">Simulation only. Approval here does not send money. Real affiliate withdrawals and the 3% fee are not yet implemented.</p><div class=\"scroll\"><table><thead><tr><th>ID</th><th>Artist</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody id=\"withdrawalRows\"></tbody></table></div></section><section id=\"artists\" class=\"panel\" hidden><h2>Registered artists and referral teams</h2><p class=\"muted\">Direct downlines are viewable individually; indirect downlines are shown as totals.</p><div class=\"scroll\"><table><thead><tr><th>Artist</th><th>Email</th><th>Plan</th><th>Status</th><th>Referrer</th><th>Direct</th><th>Indirect</th><th>Team</th></tr></thead><tbody id=\"artistRows\"></tbody></table></div><h3>Selected artist's direct downline</h3><div class=\"scroll\"><table><thead><tr><th>Artist</th><th>Email</th><th>Plan</th><th>Status</th></tr></thead><tbody id=\"directRows\"></tbody></table></div></section><section id=\"video\" class=\"panel\" hidden><h2>Homepage promotional video</h2><p class=\"muted\">Upload a short, silent MP4 or WebM clip (up to 6 MB). It will autoplay muted, loop, and resize for phones. Use a compressed clip for fast loading.</p><input type=\"file\" id=\"videoFile\" accept=\"video/mp4,video/webm\"><button id=\"uploadVideo\">Upload video</button><button id=\"removeVideo\">Remove video</button><p id=\"videoStatus\"></p><video id=\"videoPreview\" style=\"display:block;width:100%;max-width:700px;aspect-ratio:16/9;object-fit:cover;border-radius:14px;background:#100d1d\" src=\"/homepage-video\" autoplay muted loop playsinline controls></video></section><section id=\"studio\" class=\"panel\" hidden><h2>Homepage Studio</h2><p>Edit the homepage in the existing management studio, which requires the same authenticated admin session.</p><a href=\"/admin/studio\">Open protected Homepage Studio</a></section></section><p id=\"status\" role=\"status\"></p></main><script>const el=id=>document.getElementById(id);const money=v=>'$'+(Number(v||0)/100).toFixed(2);async function api(url,method='GET',data){const r=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,cache:'no-store'});const x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');return x}function showLogin(){el('login').hidden=false;el('workspace').hidden=true}function showWorkspace(){el('login').hidden=true;el('workspace').hidden=false}function cell(tr,v){const td=document.createElement('td');td.textContent=String(v??'');tr.append(td);return td}async function load(){try{const x=await api('/api/admin/affiliate-overview');showWorkspace();el('status').textContent='';el('metrics').replaceChildren();for(const [label,value] of [['Verified subscriptions',x.summary.verified_subscriptions],['Commission records',x.summary.commission_count],['Available commissions',money(x.summary.available_cents)],['Pending commissions',money(x.summary.pending_cents)]]){const d=document.createElement('div'),n=document.createElement('span'),v=document.createElement('strong');n.textContent=label;v.textContent=value;d.append(n,v);el('metrics').append(d)}el('commissions').replaceChildren();for(const c of x.commissions){const tr=document.createElement('tr');for(const v of [c.affiliate_name,c.artist_name,c.plan,c.tier===1?'Direct 25%':'Indirect 10%',money(c.amount_cents),c.status,new Date(c.created_at).toLocaleDateString()])cell(tr,v);el('commissions').append(tr)}if(!x.commissions.length){const tr=document.createElement('tr');cell(tr,'No verified subscription commissions yet.').colSpan=7;el('commissions').append(tr)}await Promise.all([loadWithdrawals(),loadArtists()])}catch(e){if(/sign-in|admin|unauthor/i.test(e.message))showLogin();el('status').textContent=e.message}}async function loadWithdrawals(){try{const x=await api('/api/demo/admin/withdrawals');el('withdrawalRows').replaceChildren();for(const w of x.withdrawals){const tr=document.createElement('tr');for(const v of [w.id,w.display_name,money(w.amount_cents),w.status])cell(tr,v);const td=document.createElement('td');if(w.status==='pending'){for(const st of ['approved','rejected']){const btn=document.createElement('button');btn.textContent=st==='approved'?'Approve demo':'Reject demo';btn.onclick=async()=>{if(!confirm('Mark demo request '+w.id+' as '+st+'? No real money will move.'))return;btn.disabled=true;try{await api('/api/demo/admin/review','POST',{id:w.id,status:st});await loadWithdrawals()}catch(e){el('status').textContent=e.message;btn.disabled=false}};td.append(btn)}}else td.textContent='Reviewed';tr.append(td);el('withdrawalRows').append(tr)}if(!x.withdrawals.length){const tr=document.createElement('tr');cell(tr,'No demo withdrawal requests.').colSpan=5;el('withdrawalRows').append(tr)}}catch(e){el('status').textContent='Demo withdrawals: '+e.message}}async function loadArtists(){try{const x=await api('/api/admin/artists');el('artistRows').replaceChildren();for(const a of x.artists){const tr=document.createElement('tr');for(const v of [a.display_name,a.email,a.plan,a.membership_status,a.referrer_name||'—',a.direct_count,a.indirect_count])cell(tr,v);const td=document.createElement('td'),btn=document.createElement('button');btn.textContent='View directs';btn.onclick=()=>loadDirects(a.id);td.append(btn);tr.append(td);el('artistRows').append(tr)}}catch(e){el('status').textContent='Artist directory: '+e.message}}async function loadDirects(id){try{const x=await api('/api/admin/artist-directs?id='+encodeURIComponent(id));el('directRows').replaceChildren();for(const a of x.directs){const tr=document.createElement('tr');for(const v of [a.display_name,a.email,a.plan,a.membership_status])cell(tr,v);el('directRows').append(tr)}if(!x.directs.length){const tr=document.createElement('tr');cell(tr,'No direct recruits.').colSpan=4;el('directRows').append(tr)}}catch(e){el('status').textContent=e.message}}el('uploadVideo').onclick=async()=>{const f=el('videoFile').files[0];if(!f)return el('videoStatus').textContent='Select a video first.';if(f.size>6000000)return el('videoStatus').textContent='Maximum file size is 6 MB.';el('videoStatus').textContent='Uploading...';const reader=new FileReader();reader.onload=async()=>{try{await api('/api/admin/homepage-video','POST',{data:reader.result});el('videoPreview').src='/homepage-video?ts='+Date.now();el('videoStatus').textContent='Homepage video saved.'}catch(e){el('videoStatus').textContent=e.message}};reader.readAsDataURL(f)};el('removeVideo').onclick=async()=>{if(!confirm('Remove homepage video?'))return;try{await api('/api/admin/homepage-video','POST',{remove:true});el('videoPreview').removeAttribute('src');el('videoStatus').textContent='Video removed.'}catch(e){el('videoStatus').textContent=e.message}};el('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/login','POST',{password:el('password').value});el('password').value='';await load()}catch(e){el('status').textContent=e.message}};el('logout').onclick=async()=>{await api('/api/admin/logout','POST',{});showLogin();el('status').textContent='Signed out.'};for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{for(const x of document.querySelectorAll('[data-tab]'))x.setAttribute('aria-selected',String(x===b));for(const id of ['overview','affiliates','withdrawals','artists','video','studio'])el(id).hidden=id!==b.dataset.tab};load();</script></body></html>";
async function ensureCoinTables(){if(!pool)return;await pool.query("CREATE TABLE IF NOT EXISTS generation_wallets(creator_id BIGINT PRIMARY KEY REFERENCES creators(id) ON DELETE CASCADE,credits INTEGER NOT NULL DEFAULT 0 CHECK(credits>=0),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await pool.query("CREATE TABLE IF NOT EXISTS generation_ledger(id BIGSERIAL PRIMARY KEY,creator_id BIGINT NOT NULL REFERENCES creators(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await pool.query("CREATE TABLE IF NOT EXISTS generation_records(id BIGSERIAL PRIMARY KEY,creator_id BIGINT NOT NULL REFERENCES creators(id),code_hash CHAR(64) NOT NULL UNIQUE,model TEXT NOT NULL,title TEXT NOT NULL,lyrics TEXT NOT NULL,style TEXT NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");await pool.query('ALTER TABLE generation_records ADD COLUMN IF NOT EXISTS generated_track_id BIGINT UNIQUE')}
async function grantWelcomeCredits(creatorId=null){if(!pool)return;await ensureCoinTables();if(creatorId!==null&&require('./lib/artist-test-access').enabled(process.env)){await require('./lib/artist-test-access').grantLyrics(pool,creatorId);return;}if(process.env.LAE_REVIEW_TEST_OPEN==='1'&&require('./lib/review-testing').enabled(process.env)){await pool.query("WITH awarded AS (INSERT INTO generation_ledger(creator_id,delta,reason,reference) SELECT id,2,'review_free_lyrics_test','review-two-lyrics-v1:' || id::text FROM creators WHERE ($1::bigint IS NULL OR id=$1::bigint) ON CONFLICT(reference) DO NOTHING RETURNING creator_id,delta), totals AS (SELECT creator_id,SUM(delta)::integer AS credits FROM awarded GROUP BY creator_id) INSERT INTO generation_wallets(creator_id,credits) SELECT creator_id,credits FROM totals ON CONFLICT(creator_id) DO UPDATE SET credits=generation_wallets.credits+EXCLUDED.credits,updated_at=NOW()",[creatorId]);return;}const sql="WITH awarded AS (INSERT INTO generation_ledger(creator_id,delta,reason,reference) SELECT id,4,'welcome_test_credits','welcome-2026:' || id::text FROM creators WHERE ($1::bigint IS NULL OR id=$1::bigint) AND NOT EXISTS(SELECT 1 FROM generation_ledger l WHERE l.creator_id=creators.id AND l.reference='artist-two-lyrics-v1:'||creators.id::text) ON CONFLICT(reference) DO NOTHING RETURNING creator_id,delta), totals AS (SELECT creator_id,SUM(delta)::integer AS credits FROM awarded GROUP BY creator_id) INSERT INTO generation_wallets(creator_id,credits) SELECT creator_id,credits FROM totals ON CONFLICT(creator_id) DO UPDATE SET credits=generation_wallets.credits+EXCLUDED.credits,updated_at=NOW()";await pool.query(sql,[creatorId])}
