 if(p==='/api/admin/generation/test-credit'&&req.method==='POST'){if(!authAdmin(req))return json(res,403,{error:'Administrator authorization required'});if(!validOrigin(req))return json(res,403,{error:'Invalid origin'});if(!pool)return json(res,503,{error:'Database unavailable'});const b=await body(req,4096);const email=String(b.email||'').trim().toLowerCase();const reference=String(b.reference||'').trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||!/^[a-zA-Z0-9_-]{8,80}$/.test(reference))return json(res,400,{error:'Valid member email and unique test reference required'});await ensureCoinTables();const db=await pool.connect();try{await db.query('BEGIN');const c=await db.query('SELECT id FROM creators WHERE LOWER(email)=$1',[email]);if(!c.rowCount){await db.query('ROLLBACK');return json(res,404,{error:'Member not found'})}const id=c.rows[0].id;const ref='test-credit:'+reference;const existing=await db.query('SELECT creator_id FROM generation_ledger WHERE reference=$1',[ref]);if(existing.rowCount){await db.query('ROLLBACK');return json(res,409,{error:'Test reference already used'})}await db.query('INSERT INTO generation_ledger(creator_id,delta,reason,reference) VALUES($1,4,$2,$3)',[id,'admin_test_credit',ref]);const w=await db.query('INSERT INTO generation_wallets(creator_id,credits) VALUES($1,4) ON CONFLICT(creator_id) DO UPDATE SET credits=generation_wallets.credits+4,updated_at=NOW() RETURNING credits',[id]);await db.query('COMMIT');return json(res,200,{ok:true,credits_added:4,balance:w.rows[0].credits,test_only:true})}catch(e){await db.query('ROLLBACK');if(e.code==='23505')return json(res,409,{error:'Test reference already used'});throw e}finally{db.release()}}
