async function grantExistingMemberTestBonus(){if(!pool)return;await ensureCoinTables();const db=await pool.connect();try{await db.query('BEGIN');await db.query("CREATE TABLE IF NOT EXISTS generation_credit_campaigns (campaign_id TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");const campaign=await db.query("INSERT INTO generation_credit_campaigns(campaign_id) VALUES('existing-members-extra-3-oct-2026') ON CONFLICT DO NOTHING RETURNING campaign_id");if(campaign.rowCount){const awarded=await db.query("WITH awarded AS (INSERT INTO generation_ledger(creator_id,delta,reason,reference) SELECT id,3,'existing_member_test_bonus','extra-3-oct-2026:' || id::text FROM creators ON CONFLICT(reference) DO NOTHING RETURNING creator_id,delta), totals AS (SELECT creator_id,SUM(delta)::integer AS credits FROM awarded GROUP BY creator_id) INSERT INTO generation_wallets(creator_id,credits) SELECT creator_id,credits FROM totals ON CONFLICT(creator_id) DO UPDATE SET credits=generation_wallets.credits+EXCLUDED.credits,updated_at=NOW() RETURNING creator_id");console.log('Existing member testing bonus applied to '+awarded.rowCount+' accounts')}await db.query('COMMIT')}catch(e){await db.query('ROLLBACK');throw e}finally{db.release()}}
